LogicDefinition.ScriptText:
#load "reference"


using System;
using System.Text;

//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           AddCountToString                                                                     //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    21.05.2025       1.3.0          Greif            Header integriert
//    04.12.2025       1.4.4          Egg              Code optimiert
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE              x              Egg              Fügt eine Zahl mit definierter Anzahl Digits an
//                                                     einen String
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik fügt eine Zahl an einen String. Zusätzlich kann definiert werden, wie viele Stellen
//    die Zahl hat
//
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////


if(String.IsNullOrEmpty(Input))
{
    return;
}



if(Enable)
{
    Output = Input + _number.ToString("D" + NumberOfDigits);

    if(ResetCounter)
    {
        _number = NumberMin;
    }

    if (TriggerCounter && !_trigger)
    {
        _number++; 

        // Zähler zurücksetzen
        if (_number > NumberMax || _number < NumberMin)
        {
            _number = NumberMin;        
        }        


    }    
    _trigger = TriggerCounter;   

}
else
{
    Output = Input;
}
